import { test, expect } from '@playwright/test';

test.describe('Record Date Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display created date on a record', async ({ page }) => {
    // Navigate to records page
    await page.getByRole('link', { name: /records/i }).click();

    // Wait for records to load
    await page.waitForLoadState('networkidle');

    // Click on first record to view details
    await page.getByRole('button', { name: /view/i }).first().click();

    // Verify created date is visible
    const createdDateLabel = page.getByText(/created date/i);
    await expect(createdDateLabel).toBeVisible();

    // Verify created date has a value
    const createdDateValue = page.getByRole('cell', { name: /\d{4}-\d{2}-\d{2}/ }).first();
    await expect(createdDateValue).toBeVisible();
  });

  test('should display last modified date on a record', async ({ page }) => {
    // Navigate to records page
    await page.getByRole('link', { name: /records/i }).click();

    // Wait for records to load
    await page.waitForLoadState('networkidle');

    // Click on first record to view details
    await page.getByRole('button', { name: /view/i }).first().click();

    // Verify last modified date is visible
    const modifiedDateLabel = page.getByText(/last modified|modified date/i);
    await expect(modifiedDateLabel).toBeVisible();

    // Verify last modified date has a value
    const modifiedDateValue = page.getByRole('cell', { name: /\d{4}-\d{2}-\d{2}/ }).nth(1);
    await expect(modifiedDateValue).toBeVisible();
  });

  test('should show both dates in record list view', async ({ page }) => {
    // Navigate to records page
    await page.getByRole('link', { name: /records/i }).click();

    // Wait for records to load
    await page.waitForLoadState('networkidle');

    // Verify created date column exists in table
    const createdDateHeader = page.getByRole('columnheader', { name: /created/i });
    await expect(createdDateHeader).toBeVisible();

    // Verify modified date column exists in table
    const modifiedDateHeader = page.getByRole('columnheader', { name: /modified|updated/i });
    await expect(modifiedDateHeader).toBeVisible();

    // Verify at least one record has dates displayed
    const firstRecordRow = page.getByRole('row').nth(1);
    await expect(firstRecordRow).toContainText(/\d{4}-\d{2}-\d{2}/);
  });

  test('should update last modified date when record is edited', async ({ page }) => {
    // Navigate to records page
    await page.getByRole('link', { name: /records/i }).click();

    // Wait for records to load
    await page.waitForLoadState('networkidle');

    // Click on first record to view details
    await page.getByRole('button', { name: /view/i }).first().click();

    // Get initial modified date
    const initialModifiedDate = await page.getByText(/last modified|modified date/i).textContent();

    // Click edit button
    await page.getByRole('button', { name: /edit/i }).click();

    // Make a change to the record
    const inputField = page.getByRole('textbox').first();
    await inputField.fill('Updated value');

    // Save the record
    await page.getByRole('button', { name: /save/i }).click();

    // Wait for save to complete
    await page.waitForLoadState('networkidle');

    // Verify modified date has been updated
    const updatedModifiedDate = await page.getByText(/last modified|modified date/i).textContent();
    expect(updatedModifiedDate).not.toBe(initialModifiedDate);
  });
});
